const fs = require('fs');
const http = require('http');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:3003/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const env = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, equalsIndex).trim();
    let value = trimmed.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function resolveDatabaseUrl(env) {
  return env.DATABASE_URL || process.env.DATABASE_URL;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);

    if (parsed.password) {
      parsed.password = 'REDACTED';
    }

    return parsed.toString();
  } catch (_) {
    return 'REDACTED';
  }
}

function redactValue(key, value) {
  if (key === 'DATABASE_URL') {
    return redactDatabaseUrl(value);
  }

  if (/PASSWORD|SECRET|TOKEN|API[_-]?KEY|ACCESS[_-]?KEY/i.test(key)) {
    return 'REDACTED';
  }

  return value;
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.entries(env).map(([key, value]) => [key, redactValue(key, value)])
  );
}

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);
    const parsedUrl = new URL(url);

    const request = http.request(
      {
        hostname: parsedUrl.hostname,
        port: parsedUrl.port,
        path: parsedUrl.pathname + parsedUrl.search,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        response.resume();
        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve();
          } else {
            reject(new Error(`Audit service returned HTTP ${response.statusCode}`));
          }
        });
      }
    );

    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

async function auditMigrationStart(env, databaseUrl) {
  await postJson(auditUrl, {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    databaseUrl: redactDatabaseUrl(databaseUrl),
    env: redactEnv(env),
  });

  console.log('Migration audit logged successfully.');
}

function getSqlMigrations(dir) {
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort();
}

async function main() {
  const env = loadEnvFile(envTestPath);
  const databaseUrl = resolveDatabaseUrl(env);

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test or environment.');
    process.exitCode = 1;
    return;
  }

  console.log('Connected to database successfully.');

  try {
    await auditMigrationStart(env, databaseUrl);
  } catch (error) {
    console.error(`Failed to log migration audit: ${error.message}`);
    process.exitCode = 1;
    return;
  }

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const migrations = getSqlMigrations(migrationsDir);

  for (const filename of migrations) {
    console.log(`Would apply migration: ${filename}`);
  }
}

main();

