#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');

function readDatabaseUrl() {
  if (!fs.existsSync(envFile)) {
    console.error(`Environment file not found: ${envFile}`);
    process.exit(1);
  }

  const envContents = fs.readFileSync(envFile, 'utf8');

  for (const line of envContents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const match = trimmed.match(/^DATABASE_URL\s*=\s*(.*)$/);
    if (match) {
      return match[1].trim().replace(/^['"]|['"]$/g, '');
    }
  }

  console.error('DATABASE_URL not found in .env.test');
  process.exit(1);
}

function main() {
  const databaseUrl = readDatabaseUrl();

  if (!databaseUrl) {
    console.error('DATABASE_URL is empty in .env.test');
    process.exit(1);
  }

  console.log('Connected successfully using DATABASE_URL from .env.test');

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  for (const file of files) {
    console.log(file);
  }
}

main();

