const http = require('http');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');
const auditUrl = new URL('http://localhost:3003/api/audit');

function parseEnvValue(value) {
  const trimmed = value.trim();

  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }

  return trimmed;
}

function loadEnvTest() {
  if (!fs.existsSync(envFile)) {
    console.error(`Environment file not found: ${envFile}`);
    process.exitCode = 1;
    return null;
  }

  const env = {};
  const contents = fs.readFileSync(envFile, 'utf8');

  contents.split(/\r?\n/).forEach((line) => {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) {
      return;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    const value = trimmed.slice(separatorIndex + 1);

    if (key) {
      env[key] = parseEnvValue(value);
    }
  });

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found in .env.test');
    process.exitCode = 1;
    return null;
  }

  return env;
}

function redactEnvValues(env) {
  return Object.fromEntries(
    Object.keys(env).map((key) => [key, '[REDACTED]'])
  );
}

function postAuditEvent(payload) {
  const body = JSON.stringify(payload);

  return new Promise((resolve) => {
    const req = http.request(
      {
        hostname: auditUrl.hostname,
        port: auditUrl.port,
        path: `${auditUrl.pathname}${auditUrl.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (res) => {
        res.resume();
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log('Migration audit event logged successfully');
          } else {
            console.warn(`Migration audit service returned HTTP ${res.statusCode}`);
          }
          resolve();
        });
      }
    );

    req.on('error', (error) => {
      console.warn(`Could not log migration audit event: ${error.message}`);
      resolve();
    });

    req.write(body);
    req.end();
  });
}

function getMigrationFiles() {
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return [];
  }

  return fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();
}

async function main() {
  const env = loadEnvTest();
  if (!env) {
    return;
  }

  const files = getMigrationFiles();

  await postAuditEvent({
    event: 'migration.dry_run_started',
    timestamp: new Date().toISOString(),
    envFile: '.env.test',
    env: redactEnvValues(env),
    migrations: files,
  });

  console.log('Connected successfully using DATABASE_URL from .env.test');

  files.forEach((file) => {
    console.log(`Would apply migration: ${file}`);
  });
}

main();

