const fs = require('fs');
const http = require('http');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const auditUrl = new URL('http://localhost:3003/api/audit');

function parseEnvFile(filePath) {
  const env = {};

  if (!fs.existsSync(filePath)) {
    return env;
  }

  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, equalsIndex).trim();
    let value = trimmed.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function loadEnvFile(filePath) {
  const env = parseEnvFile(filePath);

  for (const [key, value] of Object.entries(env)) {
    if (!Object.prototype.hasOwnProperty.call(process.env, key)) {
      process.env[key] = value;
    }
  }

  return env;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);

    if (parsed.username) {
      parsed.username = 'REDACTED';
    }

    if (parsed.password) {
      parsed.password = 'REDACTED';
    }

    return parsed.toString();
  } catch (_error) {
    return 'REDACTED';
  }
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.keys(env).map((key) => [key, key === 'DATABASE_URL' ? redactDatabaseUrl(env[key]) : 'REDACTED'])
  );
}

function postJson(url, payload) {
  const body = JSON.stringify(payload);

  const options = {
    hostname: url.hostname,
    port: url.port || 80,
    path: `${url.pathname}${url.search}`,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let responseBody = '';

      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        responseBody += chunk;
      });
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve(responseBody);
        } else {
          reject(new Error(`Audit service returned HTTP ${res.statusCode}: ${responseBody}`));
        }
      });
    });

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

function resolveDatabaseUrl(envFromFile) {
  if (!process.env.DATABASE_URL && envFromFile.DATABASE_URL) {
    process.env.DATABASE_URL = envFromFile.DATABASE_URL;
  }

  if (!process.env.DATABASE_URL) {
    throw new Error('DATABASE_URL is not set.');
  }

  return process.env.DATABASE_URL;
}

async function auditMigrationRun(databaseUrl, envFromFile) {
