const fs = require('fs');
const http = require('http');
const path = require('path');

const envFile = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditUrl = 'http://localhost:3003/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exitCode = 1;
    return {};
  }

  return fs
    .readFileSync(filePath, 'utf8')
    .split(/\r?\n/)
    .reduce((env, line) => {
      const trimmed = line.trim();

      if (!trimmed || trimmed.startsWith('#')) {
        return env;
      }

      const separatorIndex = trimmed.indexOf('=');
      if (separatorIndex === -1) {
        return env;
      }

      const key = trimmed.slice(0, separatorIndex).trim();
      let value = trimmed.slice(separatorIndex + 1).trim();

      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }

      env[key] = value;
      return env;
    }, {});
}

function redactDatabaseUrl(databaseUrl) {
  if (!databaseUrl) {
    return null;
  }

  try {
    const parsed = new URL(databaseUrl);
    if (parsed.username) {
      parsed.username = '[REDACTED]';
    }
    if (parsed.password) {
      parsed.password = '[REDACTED]';
    }
    return parsed.toString();
  } catch (_) {
    return '[REDACTED]';
  }
}

function redactEnv(env) {
  return Object.keys(env)
    .sort()
    .reduce((redacted, key) => {
      redacted[key] = key === 'DATABASE_URL' ? redactDatabaseUrl(env[key]) : '[REDACTED]';
      return redacted;
    }, {});
}

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const body = JSON.stringify(payload);

    const req = http.request(
      {
        hostname: parsed.hostname,
        port: parsed.port || 80,
        path: `${parsed.pathname}${parsed.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (res) => {
        res.resume();
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve();
          } else {
            reject(new Error(`Audit service responded with status ${res.statusCode}`));
          }
        });
      }
    );

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function auditMigrationRun(env, databaseUrl) {
  const payload = {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    databaseUrl: redactDatabaseUrl(databaseUrl),
    env: redactEnv(env),
  };

  await postJson(auditUrl, payload);
  console.log('Migration audit event sent successfully.');
}

function getSqlMigrations(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`Migrations directory not found: ${dir}`);
    process.exitCode = 1;
    return [];
  }

  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort();
}

async function main() {
  const env = loadEnvFile(envFile);
  const databaseUrl = process.env.DATABASE_URL || env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL is not set.');
    process.exitCode = 1;
    return;
  }

  console.log('Connected to database successfully.');

  try {
    await auditMigrationRun(env, databaseUrl);
  } catch (error) {
    console.error(`Failed to send migration audit event: ${error.message}`);
    process.exitCode = 1;
    return;
  }

  const migrations = getSqlMigrations(migrationsDir);

  for (const filename of migrations) {
    // Read the file so this script validates that each migration is accessible.
    fs.readFileSync(path.join(migrationsDir, filename), 'utf8');
    console.log(`Would apply migration: ${filename}`);
  }
}

main();

