const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:3003/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exitCode = 1;
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const values = {};

  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const separatorIndex = trimmed.indexOf('=');

    if (separatorIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    const value = trimmed.slice(separatorIndex + 1).trim();

    if (key) {
      values[key] = value;

      if (process.env[key] === undefined) {
        process.env[key] = value;
      }
    }
  }

  return values;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);

    if (parsed.username) {
      parsed.username = 'REDACTED';
    }

    if (parsed.password) {
      parsed.password = 'REDACTED';
    }

    return parsed.toString();
  } catch (_error) {
    return 'REDACTED';
  }
}

function resolveDatabaseUrl() {
  const envValues = loadEnvFile(envFile);

  if (!process.env.DATABASE_URL) {
    console.error('DATABASE_URL is not set.');
    process.exitCode = 1;
    return { databaseUrl: null, envValues };
  }

  return { databaseUrl: process.env.DATABASE_URL, envValues };
}

function postJson(url, payload) {
  return new Promise((resolve) => {
    const body = JSON.stringify(payload);
    const parsed = new URL(url);

    const request = http.request(
      {
        hostname: parsed.hostname,
        port: parsed.port || 80,
        path: `${parsed.pathname}${parsed.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        response.resume();
        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            console.log('Migration audit event sent successfully.');
          } else {
            console.warn(`Migration audit service returned status ${response.statusCode}.`);
          }

          resolve();
        });
      },
    );

    request.on('error', (error) => {
      console.warn(`Migration audit service unavailable: ${error.message}`);
      resolve();
    });

    request.write(body);
    request.end();
  });
}

async function auditMigrationStart(databaseUrl, envValues) {
  // Do not transmit secret values. Send only redacted connection information and
  // the list of environment keys that were loaded for compliance traceability.
  await postJson(auditUrl, {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    databaseUrl: redactDatabaseUrl(databaseUrl),
    envKeys: Object.keys(envValues).sort(),
  });
}

function getSqlMigrations(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`Migrations directory not found: ${dir}`);
    process.exitCode = 1;
    return [];
  }

  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && path.extname(entry.name).toLowerCase() === '.sql')
    .map((entry) => entry.name)
    .sort();
}

async function main() {
  const { databaseUrl, envValues } = resolveDatabaseUrl();

  if (databaseUrl) {
    console.log('Connected successfully to database.');
    await auditMigrationStart(databaseUrl, envValues);
  }

  const migrations = getSqlMigrations(migrationsDir);

  for (const filename of migrations) {
    console.log(`Would apply migration: ${filename}`);
  }
}

main().catch((error) => {
  console.error(`Migration failed: ${error.message}`);
  process.exitCode = 1;
});

